    import hashlib
    digest = hashlib.sha256()
    for path in sources():
        digest.update(path.name.encode())
        try:
            digest.update(path.read_bytes())
        except OSError:
            digest.update(b"missing")
    return digest.hexdigest()[:16]


def scratch():
