        if candidate:
            path = Path(candidate)
            try:
                path.mkdir(parents=True, exist_ok=True)
                if os.access(str(path), os.W_OK | os.X_OK):
                    return path
            except OSError:
                continue
    import tempfile
    return Path(tempfile.gettempdir())


def build():
    """Compile once per source fingerprint; reuse the cached binary."""
    global _BINARY, _FAILED
    if _FAILED:
